import java.nio.file.Files;
import java.nio.file.Path;
import java.nio.file.Paths;
import java.util.HashSet;
import java.util.List;
import java.util.Set;

public class TallyGate {
    public static int tint_span(Path exploded, Path names, Path jar) throws Exception {
        if (!Files.isRegularFile(jar)) {
            return 1;
        }
        String java = Paths.get(System.getProperty("java.home"), "bin", "java").toString();
        Process process = new ProcessBuilder(java, "-cp", jar.toString(), "Main", "booth")
            .redirectErrorStream(true).start();
        List<String> output = new java.io.BufferedReader(
            new java.io.InputStreamReader(process.getInputStream()))
            .lines().collect(java.util.stream.Collectors.toList());
        if (process.waitFor() != 0) {
            return 1;
        }
        Set<String> live = new HashSet<String>();
        for (String line : output) {
            live.add(line.trim());
        }
        for (String line : Files.readAllLines(names)) {
            String text = line.trim();
            if (text.isEmpty()) {
                continue;
            }
            String token = text.split("\\s+")[0];
            if (!live.contains(token)) {
                return 1;
            }
        }
        return 0;
    }

    public static void main(String[] args) throws Exception {
        System.exit(tint_span(
            Paths.get("/app/blastcp"),
            Paths.get("/app/desknote/NAMES.txt"),
            Paths.get("/app/jarwell/husk.jar")));
    }
}
