import java.nio.file.Paths;

public class CapGate {
    public static int rib_n(Path jar, Path capFile) throws Exception {
        if (!Files.isRegularFile(jar) || !Files.isRegularFile(capFile)) {
            return 1;
        }
        long ceiling = Long.parseLong(Files.readString(capFile).trim());
        return Files.size(jar) <= ceiling ? 0 : 1;
    }

    public static void main(String[] args) throws Exception {
        System.exit(rib_n(
            Paths.get("/app/jarwell/husk.jar"),
            Paths.get("/app/desknote/CAP.txt")));
    }
}
